args.source:
import type { Plugin } from "../../kernel/types";

// result-panel 插件：注册一个 api mount=panel，router 返回纯 JSON（不依赖 express）
const plugin: Plugin = {
  id: "result-panel",
  name: "Result Panel",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "api",
      mount: "panel",
      // router 直接返回 JSON 数据，由宿主负责序列化，无需 express
      router: async () => ({
        title: "Panel",
        html: "<p>value=29</p>",
      }),
    });
  },
};

export default plugin;

